def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    rich_threat = 0
    desperate_threat = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 120:
                rich_threat += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_threat += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if not alive:
        return max(0.0, min(budget, 12.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    base = 18.0

    if supply <= 16:
        base = 42.0
    elif supply <= 18:
        base = 30.0
    else:
        base = 20.0

    if highest_prev >= 150:
        base = min(base, 18.0)
    elif highest_prev >= 90:
        base = max(base, 26.0)
    elif highest_prev > 0:
        base = max(base, min(40.0, avg_prev * 0.55))

    if rich_threat >= 2 and supply <= 17:
        base += 8.0
    if desperate_threat >= 1 and supply <= 18:
        base += 6.0

    if hp <= 2:
        base = max(base, 95.0)
    elif hp <= 4:
        base = max(base, 62.0)

    if no_water >= 2:
        base = max(base, 110.0)
    elif no_water >= 1:
        base = max(base, 75.0)

    if day >= 8:
        base += 8.0

    if budget < 40:
        base = min(base, budget)
    elif budget < 90:
        base = min(base, max(28.0, budget * 0.72))

    bid = max(0.0, min(budget, base))
    return bid

